package com.bank.catalogue;

import java.util.*;
import java.util.logging.*;

public class FilterMapDemo {
    private static final Logger log = Logger.getLogger("Catalogue");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        Map<String, Integer> fees = new LinkedHashMap<>();
        fees.put("SMS Alerts", 50);
        fees.put("Locker", 250);
        fees.put("Cheque Book", 100);   // exactly 100 → excluded (> is strict)
        fees.put("Wealth Advisory", 500);
        CatalogueService service = new CatalogueService();

        Map<String, Integer> premium = service.premium(fees);
        log.info(() -> "Premium products (fee > 100): " + premium);
    }
}

// ─── Would be in service/CatalogueService.java ───
class CatalogueService {
    Map<String, Integer> premium(Map<String, Integer> fees) {
        return fees.entrySet().stream()
            .filter(e -> e.getValue() > 100)                 // strictly above 100
            .collect(java.util.stream.Collectors.toMap(
                Map.Entry::getKey, Map.Entry::getValue,
                (a, b) -> a, LinkedHashMap::new));            // keep order
    }
}
